const cfg = $('Repo Config').first().json;
const drive = $('Google Drive Trigger (Deleted)').first().json;
const token = cfg.githubToken || $vars.GITHUB_PAT || $vars.githubToken || '';
if (!token) throw new Error('Set Repo Config.githubToken');

const rawName = String(drive.name || drive.fileName || '');
if (!rawName) throw new Error('Deleted Drive event missing file name');
const base = rawName.replace(/\.[^.]+$/, '').replace(/[^a-zA-Z0-9_-]/g, '_').toLowerCase() || 'asset';
const ext = (rawName.match(/\.([a-z0-9]+)$/i)?.[1] || 'png').toLowerCase();
const textureRel = `textures/${base}.${ext === 'jpeg' ? 'jpg' : ext}`;
const texturePath = `${cfg.cdnPrefix}/${textureRel}`;
const manifestPath = `${cfg.cdnPrefix}/manifest.json`;

const api = `https://api.github.com/repos/${cfg.owner}/${cfg.repo}/contents`;
const headers = {
  Authorization: `Bearer ${token}`,
  Accept: 'application/vnd.github+json',
  'X-GitHub-Api-Version': '2022-11-28',
  'User-Agent': 'n8n-coinduel-cdn-delete',
};

async function getFile(path) {
  const url = `${api}/${path}?ref=${encodeURIComponent(cfg.branch)}`;
  const res = await this.helpers.httpRequest({ method: 'GET', url, headers, ignoreHttpStatusErrors: true });
  if (res && res.sha) return res;
  return null;
}

async function deletePath(path, sha, message) {
  const url = `${api}/${path}`;
  return this.helpers.httpRequest({
    method: 'DELETE',
    url,
    headers,
    body: { message, sha, branch: cfg.branch },
    json: true,
    ignoreHttpStatusErrors: true,
  });
}

// 1) Delete texture if present
const tex = await getFile.call(this, texturePath);
let deletedTexture = false;
if (tex && tex.sha) {
  await deletePath.call(this, texturePath, tex.sha, `cdn: delete ${textureRel} (removed from Google Drive)`);
  deletedTexture = true;
}

// 2) Also try matching meme json (editor/n8n uploads)
const memePath = `${cfg.cdnPrefix}/memes/${base}.json`;
const memeFile = await getFile.call(this, memePath);
let deletedMemeJson = false;
if (memeFile && memeFile.sha) {
  await deletePath.call(this, memePath, memeFile.sha, `cdn: delete memes/${base}.json (removed from Google Drive)`);
  deletedMemeJson = true;
}

// 3) Patch memes/index.json if present
const indexPath = `${cfg.cdnPrefix}/memes/index.json`;
const indexFile = await getFile.call(this, indexPath);
if (indexFile && indexFile.content) {
  try {
    const text = Buffer.from(indexFile.content, 'base64').toString('utf8');
    const idx = JSON.parse(text);
    const list = Array.isArray(idx) ? idx : (idx.memes || idx.items || []);
    const next = list.filter((m) => m && (m.id || m.memeId || m.name) !== base);
    if (next.length !== list.length) {
      const body = Array.isArray(idx) ? next : { ...idx, memes: next };
      const b64 = Buffer.from(JSON.stringify(body, null, 2) + '\n', 'utf8').toString('base64');
      await this.helpers.httpRequest({
        method: 'PUT',
        url: `${api}/${indexPath}`,
        headers,
        body: { message: `cdn: drop ${base} from meme index`, content: b64, branch: cfg.branch, sha: indexFile.sha },
        json: true,
      });
    }
  } catch (_) {}
}

// 4) Remove from permanent manifest.json
const manFile = await getFile.call(this, manifestPath);
if (!manFile || !manFile.content) {
  return [{ json: { ok: true, deletedTexture, deletedMemeJson, note: 'manifest missing — nothing else to do', textureRel } }];
}
const manText = Buffer.from(manFile.content, 'base64').toString('utf8');
const manifest = JSON.parse(manText);
if (!Array.isArray(manifest.items)) manifest.items = [];
const before = manifest.items.length;
manifest.items = manifest.items.filter((it) => {
  if (!it || !it.filename) return true;
  if (it.filename === textureRel) return false;
  if (it.filename === `memes/${base}.json`) return false;
  return true;
});
manifest.version = Number(manifest.version || 0) + 1;
const manB64 = Buffer.from(JSON.stringify(manifest, null, 2) + '\n', 'utf8').toString('base64');
await this.helpers.httpRequest({
  method: 'PUT',
  url: `${api}/${manifestPath}`,
  headers,
  body: {
    message: `cdn: bump manifest after deleting ${textureRel}`,
    content: manB64,
    branch: cfg.branch,
    sha: manFile.sha,
  },
  json: true,
});

return [{
  json: {
    ok: true,
    textureRel,
    deletedTexture,
    deletedMemeJson,
    removedManifestItems: before - manifest.items.length,
    manifestVersion: manifest.version,
    note: 'jsDelivr may lag 1–5 min',
  },
}];
